<?php namespace App\Models;use Illuminate\Foundation\Auth\User as Authenticatable;use Illuminate\Database\Eloquent\Factories\HasFactory;use Illuminate\Notifications\Notifiable;class User extends Authenticatable{use HasFactory,Notifiable;protected $fillable=['name','nim','email','password','role','status_anggota','department_id'];protected $hidden=['password','remember_token'];protected function casts():array{return ['email_verified_at'=>'datetime','password'=>'hashed'];}public function department(){return $this->belongsTo(Department::class);}public function invoices(){return $this->hasMany(Invoice::class,'member_id');}}